export async function api(url, method = 'GET', data, options = {}) {
  const response = await fetch(url, { method, credentials: 'same-origin', cache: 'no-store', ...options, headers: { ...(data !== undefined ? { 'Content-Type': 'application/json' } : {}), ...options.headers }, body: data !== undefined ? JSON.stringify(data) : undefined });
  let result; try { result = await response.json(); } catch { throw Error('The service returned an unreadable response. Please try again.'); }
  if (!response.ok) { const error = new Error((result.error || 'Request failed') + (result.reference ? ' Reference: ' + result.reference : '')); error.status = response.status; error.details = result; throw error; }
  return result;
}
function toast(message, error = false) { clearTimeout(toastTimer); $('toast').textContent = message; $('toast').className = 'toast' + (error ? ' error' : ''); $('toast').hidden = false; toastTimer = setTimeout(() => { $('toast').hidden = true; }, 5000); }
function keyFor(scope, payload) { const storageKey = 'lae_request:' + scope, encoded = JSON.stringify(payload); let old = requestKeys.get(scope); if (!old) try { old = JSON.parse(sessionStorage.getItem(storageKey)); } catch {} if (!old || old.payload !== encoded) old = { payload: encoded, key: crypto.randomUUID() }; requestKeys.set(scope, old); try { sessionStorage.setItem(storageKey, JSON.stringify(old)); } catch {} return old.key; }
function clearKey(scope) { requestKeys.delete(scope); try { sessionStorage.removeItem('lae_request:' + scope); } catch {} }
