function formData(form) { return Object.fromEntries(new FormData(form)); }
function bindForm(form, action) { bindPasswordConfirmation(form); form.onsubmit = async event => { event.preventDefault(); const buttons = [...form.querySelectorAll('button[type=submit]')]; const status = form.querySelector('.form-status'); buttons.forEach(b => { b.disabled = true; b.dataset.originalText = b.textContent; b.textContent = 'Please wait…'; }); if (status) { status.textContent = ''; status.classList.remove('error'); }
  try { await action(formData(form), form); } catch (error) { if (status) { status.textContent = error.message; status.classList.add('error'); } else toast(error.message, true); } finally { buttons.forEach(b => { b.disabled = false; b.textContent = b.dataset.originalText; }); } }; }
