async function route(focus=false){
  const token=++routeVersion,url=new URL(location.href),view={active:()=>token===routeVersion,set:html=>{if(token!==routeVersion)return false;$('page').innerHTML='<div class="page-content">'+html+'</div>';currencyDisplay.paint();return true;}};
  view.set('<div class="skeleton-page" aria-label="Loading page"><div></div><div></div></div>');
  if(url.pathname==='/listener/account')activeAuthRole='listener';
  if(url.pathname==='/account'&&['artist','listener'].includes(url.searchParams.get('role'))){activeAuthRole=url.searchParams.get('role');try{sessionStorage.setItem('lae_active_role',activeAuthRole);}catch{}}
  await refreshSession();if(!view.active())return;
  const aliases={'/artist':'/workspace','/artist.html':'/workspace','/artist/profile-photo':'/workspace','/listen':'/discover','/music':'/discover','/music.html':'/discover','/start':'/join','/get-started':'/join','/dashboard':'/workspace','/earnings':'/workspace','/affiliate-links':'/partners','/music-prompt-studio':'/studio','/music-prompt-studio.html':'/studio','/admin/studio':'/admin/console','/listener/account':'/join','/listener/dashboard':'/library','/admin':'/admin/console','/admin.html':'/admin/console','/admin/login':'/admin/console','/admin/withdrawals':'/admin/console','/admin-withdrawals':'/admin/console'};const originalPath=url.pathname;if(aliases[originalPath])url.pathname=aliases[originalPath];if(['/start','/get-started'].includes(originalPath)){if(!url.searchParams.has('role'))url.searchParams.set('role','artist');if(url.hash!=='#signin')url.searchParams.set('mode','register');}if(originalPath==='/listener/account'){url.searchParams.set('role','listener');if(session.listener)url.pathname='/account';}if(['/artist','/artist.html'].includes(originalPath))url.searchParams.set('tab','catalog');if(originalPath==='/artist/profile-photo')url.searchParams.set('tab','profile');if(originalPath==='/earnings')url.searchParams.set('tab','finance');if(originalPath.includes('withdrawals'))url.searchParams.set('section','withdrawals');
  document.querySelectorAll('.sidebar nav a').forEach(a=>{const path=new URL(a.href).pathname;if(path===url.pathname||(path==='/'&&url.pathname==='/discover'))a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
  $('global-query').value=url.searchParams.get('q')||'';document.title=({ '/':'Discover','/discover':'Discover','/artists':'Artists','/library':'Your library','/workspace':'Artist workspace','/studio':'AI music studio','/partners':'Partners & Affiliate Network','/account':'Your account','/join':'Welcome','/premium':'Premium listening','/offline':'Offline library','/admin/console':'Administration' }[url.pathname]||'Discover')+' | LAE-MUSIC';
  if(!sessionVerified && ['/account','/studio','/workspace','/library','/partners','/admin/console'].includes(url.pathname)){sessionUnavailable(view);return;}
  try{const screens={'/offline':view=>offlinePage(view,{offline,player,toast,route:()=>route(true),refresh:refreshSession}),'/premium':(view,url)=>premiumPage(view,url,{api,e,session,heading,notice,buttonLink,bindForm,keyFor,clearKey,toast,route,date,currencyDisplay,navigate,actionDialog,refreshSession}),'/admin/enroll':(view,url)=>operatorEnrollmentPage(view,url,{api,e,heading,notice,bindForm,refreshSession,navigate,toast}),'/recover':(view,url)=>recoveryPage(view,url,accountSecurityContext()),'/verify-email':(view,url)=>recoveryPage(view,url,accountSecurityContext()),'/':discover,'/index.html':discover,'/discover':discover,'/artists':artists,'/library':library,'/workspace':workspace,'/studio':studio,'/partners':partners,'/account':account,'/join':join,'/admin/console':adminPage};await (screens[url.pathname]||discover)(view,url);}catch(error){if(view.active())view.set(empty(error.status===401?'Sign in to continue':'This page is taking a moment',error.message,error.status===401?buttonLink('/join','Sign in'):'<button class="button secondary" id="page-retry">Try again</button>',error.status!==401));if($('page-retry'))$('page-retry').onclick=()=>route();}
  if(view.active()&&focus){window.scrollTo({top:0,behavior:'instant'});$('page').focus({preventScroll:true});}
}
